#include "music.h"

#include "config.h"
#include "resources.h"

// One XGM2 blob per PC music file. Names are generated by rescomp from the
// XGM2 lines in res/resources.res and the VGMs written by
// tools/convert_music.py.
static const u8 *const music_tracks[MUSIC_COUNT] = {
    [MUSIC_OPENING]        = mus_opening,
    [MUSIC_INTRO_SCENE]    = mus_intro_scene,
    [MUSIC_SELECTOR]       = mus_selector,
    [MUSIC_SELECTOR_ALT]   = mus_selector_alt,
    [MUSIC_BOSS_INTRO]     = mus_boss_intro,
    [MUSIC_CASTLE_INTRO]   = mus_castle_intro,
    [MUSIC_CASTLE_INTRO_ALT] = mus_castle_intro_alt,
    [MUSIC_BOSS]           = mus_boss,
    [MUSIC_FINAL_BOSS]     = mus_final_boss,
    [MUSIC_GOT_WEAPON]     = mus_got_weapon,
    [MUSIC_GAME_OVER]      = mus_game_over,
    [MUSIC_STAGE_COMPLETE] = mus_stage_complete,
    [MUSIC_ENEMY_PARADE]   = mus_enemy_parade,
    [MUSIC_END_ANIMATION]  = mus_end_animation,
    [MUSIC_END_CREDITS]    = mus_end_credits,
    [MUSIC_TRANSPORTERS]   = mus_transporters,
    [MUSIC_STAGE0]         = mus_stage0,
    [MUSIC_STAGE1]         = mus_stage1,
    [MUSIC_STAGE2]         = mus_stage2,
    [MUSIC_STAGE3]         = mus_stage3,
    [MUSIC_STAGE4]         = mus_stage4,
    [MUSIC_STAGE5]         = mus_stage5,
    [MUSIC_STAGE6]         = mus_stage6,
    [MUSIC_STAGE7]         = mus_stage7,
    [MUSIC_STAGE8]         = mus_stage8,
    [MUSIC_STAGE9]         = mus_stage9,
    [MUSIC_STAGE10]        = mus_stage10,
    [MUSIC_STAGE11]        = mus_stage11,
    [MUSIC_STAGE12]        = mus_stage12,
    [MUSIC_STAGE13]        = mus_stage13,
};

static const u8 *current_track;
static bool playing;

// PC file_config volume_music (0..100). Here 4 steps: XGM2 takes 0..100 for
// the FM and PSG halves of the track, and it resets both when a track starts,
// so every play re-applies the level.
static u8 music_level = 3;

void music_set_volume(u8 level)
{
    music_level = (level > 3) ? 3 : level;
    const u16 v = (u16)(music_level * 33);      // 0 / 33 / 66 / 99
    XGM2_setFMVolume(v);
    XGM2_setPSGVolume(v);
}

u8 music_get_volume(void) { return music_level; }

// XGM2_load swaps the sample table under a playing track, and the Z80 driver
// only acts on a stop a couple of frames later: starting another track in the
// same frame as the stop left it silent (castle path -> boss intro, ending
// scene -> walking parade). music_play waits those frames when a stop is fresh.
static bool stop_pending;

void music_stop(void)
{
    // Always talk to the driver. The `playing` flag is the port's own and a
    // single desync leaves the previous track audible while music_stop() does
    // nothing - a skipped boss intro then still "plays" its jingle.
    XGM2_stop();
    playing = FALSE;
    stop_pending = TRUE;    // a stop is always fresh: music_play waits 2 frames
}

void music_play(MusicId id)
{
    if (id <= MUSIC_NONE || id >= MUSIC_COUNT) {
        music_stop();
        return;
    }
    const u8 *track = music_tracks[id];
    if (!track) {
        music_stop();
        return;
    }
    if (!config_is_sound_on()) {
        music_stop();
        current_track = track;
        return;
    }
    if (playing && track == current_track) return;
    if (playing) {                      // another track is running: stop it first
        XGM2_stop();
        playing = FALSE;
        stop_pending = TRUE;
    }
    if (stop_pending) {
        SYS_doVBlankProcess();
        SYS_doVBlankProcess();
        stop_pending = FALSE;
    }
    current_track = track;
    XGM2_play(track);
    music_set_volume(music_level);
    playing = TRUE;
}

void music_play_stage(u8 stage)
{
    if (stage < 14)
        music_play((MusicId)(MUSIC_STAGE0 + stage));
    else
        music_play(MUSIC_OPENING);
}

void music_resume(void)
{
    if (!current_track) return;
    if (!config_is_sound_on()) {
        music_stop();
        return;
    }
    if (!playing) {
        XGM2_play(current_track);
        playing = TRUE;
    }
}

#ifdef MD_WALK_AUDIO_DIAG
#include "dbgprint.h"
// One state line: the port's own flag against what the Z80 driver reports.
void music_diag(const char *tag)
{
    dbg_print("MUS %s: playing=%u xgm2=%u level=%u pending=%u same=%u sound=%u\n", tag,
              (unsigned)playing, (unsigned)XGM2_isPlaying(), (unsigned)music_level,
              (unsigned)stop_pending, (unsigned)(current_track == music_tracks[MUSIC_END_ANIMATION]),
              (unsigned)config_is_sound_on());
}
#endif
